Translate("frFR", "swamp-of-sorrows", {
	title = "Marais des Chagrins",
	aliases = { "le Marais des Chagrins" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Marais des Chagrins est un pays englouti d'eaux noires, de mousse pendante et de pluie sans fin, au sud-est des {link:eastern-kingdoms}Royaumes de l'est{/link}. Il s'étend à l'est du {link:deadwind-pass}Défilé de Deuillevent{/link} et au nord des {link:blasted-lands}Terres foudroyées{/link}, et sa côte est se brise contre la Mer interdite. Ses arbres ont de l'eau jusqu'aux genoux, ses sentiers disparaissent sous la boue, et ses mares abritent crocilisques, grandes araignées et enchevêtrements d'herbes vivantes qui marchent. Aucun royaume ne l'a jamais dompté. Les orcs de la {link:horde}Horde{/link} tiennent une forteresse en son cœur, une petite compagnie d'exilés s'accroche à sa lisière ouest, les murlocs pullulent le long de sa côte, et des dragons verts montent une garde silencieuse sur un lac où repose, englouti, un temple troll.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte qui nomma le premier le marais, ni pourquoi on l'appela un lieu de chagrin. Ce dont on se souvient, c'est qu'il est depuis longtemps une terre d'exilés. Quand les trolls gurubashi renversèrent leur dieu du sang {link:hakkar}Hakkar{/link}, ils chassèrent ses prêtres, les Atal'ai, des jungles du sud. Les Atal'ai s'enfuirent vers le nord dans ces marécages. Là, ils élevèrent un grand temple, le temple d'{link:temple-of-atal-hakkar}Atal'Hakkar{/link}, où ils comptaient rappeler leur dieu dans le monde. Le vol vert d'{red:ysera}Ysera{/red} ne le permit pas. Les dragons brisèrent le temple et l'engloutirent sous les eaux du {link:pool-of-tears}Bassin des larmes{/link}, et il y repose encore. Aucune chronique n'en donne l'année.

Au sud du marais s'étendait le Noir Marécage. C'est là que s'ouvrit la {link:dark-portal}Porte des Ténèbres{/link}, et c'est de là que la {link:horde}Horde{/link} orque partit faire la guerre au royaume d'{link:azeroth}Azeroth{/link} lors de la {link:first-war}Première Guerre{/link}. Le marais fut le premier voisin de la Horde en ce monde.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Le marais est une terre disputée. Le chef de guerre {link:thrall}Thrall{/link} tient la forteresse de {link:stonard}Stonard{/link} en son centre, et ses orcs ont envoyé des émissaires apprendre ce qu'il advint du temple englouti. L'{link:alliance}Alliance{/link} n'y tient aucune ville. Ses caravanes ne font que le traverser sur la longue route qui va du {link:duskwood}Bois de la Pénombre{/link} à {link:nethergarde-keep}Rempart-du-Néant{/link}, et beaucoup n'arrivent pas. Au nord, un peuple appelé les Perdus s'en prend à quiconque s'approche de son village. À l'ouest, une bande d'exilés draeneï, qui partagent le sang des Perdus mais pas leur folie, se cachent au {link:the-harborage}Havre boueux{/link}. Le long de la côte est, les murlocs s'enhardissent à chaque saison. Et au-dessus de tout cela, les dragons verts tournoient et attendent, gardant le temple contre le jour où ses prêtres s'agiteront de nouveau.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les orcs de {link:stonard}Stonard{/link}.{/b} Guerriers, éclaireurs et marchands de la {link:horde}Horde{/link} qui tiennent l'unique forteresse du marais, et qui gardent ses routes et sa côte.
• {b}Les draeneï du {link:the-harborage}Havre boueux{/link}.{/b} Une petite compagnie d'exilés à l'ouest, venus de très loin jusqu'à {link:azeroth}Azeroth{/link}, qui craignent désormais leurs propres parents.
• {b}Les Perdus.{/b} Parents des draeneï, rendus fous par le long voyage qui les amena ici. Ils tiennent le {link:fallow-sanctuary}Sanctuaire des friches{/link} au nord.
• {b}Le vol vert.{/b} Des dragonnets, des wyrmides et des fléaux-d'écailles du vol d'Ysera gardent le {link:pool-of-tears}Bassin des larmes{/link} et les terres alentour. Un dragon nommé {link:itharius}Itharius{/link} habite une caverne au sud-ouest.
• {b}Les murlocs.{/b} Les tribus de {link:murlocs}murlocs{/link} de la {link:misty-reed-strand}Grève de Brumejonc{/link} pullulent le long de la côte est.
• {b}Les bêtes du marécage.{/b} Crocilisques dents-de-scie, jaguars, panthères, grandes araignées et les herbes marcheuses qu'on appelle marche-marais et horreurs enchevêtrées.
• {b}Les Atal'ai.{/b} Les prêtres trolls d'{link:hakkar}Hakkar{/link} demeurent encore dans le temple englouti sous le Bassin des larmes.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'exil des Atal'ai.{/b} Chassés par les Gurubashi, les prêtres d'{link:hakkar}Hakkar{/link} élevèrent leur temple dans le marais.
• {b}L'engloutissement du temple.{/b} Le vol vert fracassa le temple et le noya, afin que le dieu du sang ne puisse revenir par lui.
• {b}La {link:first-war}Première Guerre{/link}.{/b} La {link:dark-portal}Porte des Ténèbres{/link} s'ouvrit dans le Noir Marécage, au sud, et la {link:horde}Horde{/link} posa pour la première fois le pied en ce monde à la lisière du marais.
• {b}La fondation de {link:stonard}Stonard{/link}.{/b} Aucune chronique ne rapporte quand les orcs élevèrent Stonard. C'est aujourd'hui la forteresse du chef de guerre dans le sud, ravitaillée par une longue route depuis le camp de {link:grom-gol-base-camp}Grom'gol{/link}, dans la {link:stranglethorn-vale}Vallée de Strangleronce{/link}.
• {b}Le temps présent.{/b} La Horde étudie le temple, l'{link:alliance}Alliance{/link} presse ses caravanes, et les dragons attendent.]=],
		},
		{
			title = "Récits du marais",
			text = [=[• La {link:explorers-league}Ligue des explorateurs{/link} d'{link:ironforge}Ironforge{/link} cherche depuis longtemps le temple d'{link:temple-of-atal-hakkar}Atal'Hakkar{/link}. Un vieux {link:dwarves}nain{/link} de la Ligue survola le marais à dos de griffon et ne le trouva jamais. On ne le découvrit que depuis le sol, englouti sous le {link:pool-of-tears}Bassin des larmes{/link}.
• Les draeneï appellent un cristal sacré le draenéthyste. On dit qu'il vient d'un lieu où les montagnes volent et où règnent les démons. Un chaman des centaures de {link:desolace}Désolace{/link} fit un jour chercher un éclat de ce cristal dans le marais.
• Un courrier du {link:kirin-tor}Kirin Tor{/link} perdit un jour ici un précieux essai. Il avait été écrit par {link:khadgar}Khadgar{/link} et devait être porté à {link:nethergarde-keep}Rempart-du-Néant{/link}, et les herbes marcheuses du marécage le lui prirent.
• Des énigmes griffonnées sont laissées aux chasseurs de trésors sous un vieux pont à l'ouest du marais, près de la route du {link:deadwind-pass}Défilé de Deuillevent{/link}. Les énigmes parlent d'un homme nommé Cortello, et elles mènent par-delà la mer et retour.
• Les gobelins paient bien la poussière de rêve, une poudre scintillante recueillie sur les dragonnets du marais.]=],
		},
	},
})

Translate("frFR", "stonard", {
	title = "Stonard",
	sections = {
		{
			title = "Résumé",
			text = [=[Stonard est la forteresse de la {link:horde}Horde{/link} au cœur du marais. Ses murs de pierre sombre et de lourdes poutres s'élèvent sur une terre sèche parmi les mares, et ses tours dominent des lieues de roseaux et d'eau. C'est le siège le plus solide du chef de guerre au sud des {link:eastern-kingdoms}Royaumes de l'est{/link}. D'ici, des estafettes portent les ordres jusqu'aux {link:blasted-lands}Terres foudroyées{/link}, des coursiers portent les rapports à {link:kargath}Kargath{/link} dans les {link:badlands}Terres ingrates{/link}, et des coursiers du vent volent vers le nord. Des maîtres de toutes les vocations ont leurs salles dans les murs, et un marchand expédie la viande de la côte jusqu'à {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Entre les murs",
			text = [=[Stonard a un prisonnier. Un espion humain de l'{link:alliance}Alliance{/link} est gardé sous surveillance, et il prétend connaître une trahison qui s'étend au-delà de l'Alliance elle-même. La forteresse abrite aussi l'émissaire du chef de guerre, {link:fel-zerul}Fel'zerul{/link}, envoyé pour découvrir le sort du temple englouti.]=],
		},
	},
})

Translate("frFR", "pool-of-tears", {
	title = "Bassin des larmes",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bassin des larmes est un lac large et immobile à l'est du marais. Des colonnes brisées et des restes de vieux escaliers émergent de ses hauts-fonds. Sous ses eaux repose le temple d'{link:temple-of-atal-hakkar}Atal'Hakkar{/link}, que le vol vert brisa et engloutit afin que les prêtres d'{link:hakkar}Hakkar{/link} ne puissent jamais achever leur invocation. On trouve encore des fragments des Atal'ai dans la boue de ses rives : idoles, fétiches et pierres gravées. Les dragons du vol d'Ysera gardent le lac. Des wyrmides et des fléaux-d'écailles se tiennent sur ses berges, et ils ne souffrent personne près d'eux sans raison. Les Atal'ai demeurent encore dans les salles englouties en dessous.]=],
		},
	},
})

Translate("frFR", "fallow-sanctuary", {
	title = "Sanctuaire des friches",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Sanctuaire des friches est le village des Perdus, au nord du marais. Ses huttes de roseaux et de peaux se serrent autour de feux de cuisine, et ses chasseurs, ses pêcheurs et ses voyants en partent dans le marécage. Les Perdus ressemblent aux draeneï du {link:the-harborage}Havre boueux{/link}, car ils formaient jadis un seul peuple. Mais le long voyage qui les amena sur {link:azeroth}Azeroth{/link} brisa leur esprit, et ils capturent ou tuent désormais quiconque s'égare près d'eux. Des biens volés s'entassent parmi leurs huttes : des cristaux sacrés de draenéthyste pris au Havre boueux, et les chariots d'une caravane de l'{link:alliance}Alliance{/link}. Leur chef règne sur le village. Un Perdu nommé {link:ongeku}Ongeku{/link} y garde pour lui un éclat de draenéthyste.]=],
		},
	},
})

Translate("frFR", "the-harborage", {
	title = "Le Havre boueux",
	aliases = { "Havre boueux" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Havre boueux est un petit refuge au nord-ouest du marais, où une bande d'exilés draeneï a élu domicile. Ils sont peu nombreux et mal armés. Leurs parents, les Perdus du {link:fallow-sanctuary}Sanctuaire des friches{/link}, ont volé leurs cristaux sacrés, et une brute nommée {link:noboru-the-cudgel}Noboru{/link} les traque depuis des mois avec son gourdin. {link:magtoor}Magtoor{/link} parle au nom des exilés, et un travailleur du cuir nommé Masat T'andr œuvre parmi eux. Ils accueillent les voyageurs de toute bannière qui viennent en paix, car ils n'ont pas la force de renvoyer quiconque.]=],
		},
	},
})

Translate("frFR", "itharius-s-cave", {
	title = "Caverne d'Itharius",
	sections = {
		{
			title = "Résumé",
			text = [=[La Caverne d'Itharius se trouve à l'extrême sud-ouest du marais, cachée parmi des arbres ruisselants près des confins des {link:blasted-lands}Terres foudroyées{/link}. C'est l'antre d'{link:itharius}Itharius{/link}, un dragon du vol vert. De jeunes dragonnets de son espèce dorment et jouent dans le marécage autour de son entrée, et la poussière qui tombe de leurs ailes luit comme du givre dans la pénombre. Peu viennent ici sans y être invités. Ceux qui viennent cherchent d'ordinaire une aide que seul un dragon peut donner.]=],
		},
	},
})

Translate("frFR", "misty-reed-strand", {
	title = "Grève de Brumejonc",
	sections = {
		{
			title = "Résumé",
			text = [=[La Grève de Brumejonc est la longue côte orientale du marais, où le marécage cède la place au sable et au ressac gris de la Mer interdite. Les murlocs se pressent sur ses plages : pillards, mangeurs de chair, cracheurs d'encre et oracles. De grands rampants trottinent parmi les rochers, et des happeurs dents-de-scie se tapissent dans les hauts-fonds. À son extrémité sud se dresse le Poste de Brumejonc, un petit camp de la {link:horde}Horde{/link}. Ses orcs surveillent la mer, et ils donneront l'alarme à {link:stonard}Stonard{/link} si jamais les murlocs viennent en force.]=],
		},
	},
})

Translate("frFR", "misty-valley", {
	title = "Vallée des brumes",
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée des brumes est la porte occidentale du marais, là où les terres mortes du {link:deadwind-pass}Défilé de Deuillevent{/link} descendent vers le marécage. Le brouillard stagne dans ses creux à toute heure. Les herbes marcheuses du marais sont ici au plus fort : de vieux marche-marais lourds de mousse, et un grand que les orcs appellent le Seigneur de la fange, qui erre dans les mares de l'extrême ouest. Les voyageurs venus de l'ouest traversent d'abord la vallée. C'est l'avertissement que le marais leur donne de ce qui les attend.]=],
		},
	},
})

Translate("frFR", "sorrowmurk", {
	title = "Noirchagrin",
	sections = {
		{
			title = "Résumé",
			text = [=[Noirchagrin est le marécage de l'extrême est, entre le {link:pool-of-tears}Bassin des larmes{/link} et la mer. C'est le coin le plus sinistre d'une terre sinistre. Ici, les plus anciens draconiens du vol vert montent la garde, et le capitaine draconien appelé Wyrmak commanderait les patrouilles autour du temple. Des panthères des ombres rôdent dans les roseaux. Même les orcs de {link:stonard}Stonard{/link} passent rarement par là, à moins d'y être obligés.]=],
		},
	},
})

Translate("frFR", "stagalbog", {
	title = "Stagalbog",
	aliases = { "Caverne de Stagalbog" },
	sections = {
		{
			title = "Résumé",
			text = [=[Stagalbog est une étendue de mares pourrissantes au sud-est du marais. Des horreurs enchevêtrées d'herbes et de racines pataugent dans ses eaux, et les fléaux-d'écailles du vol vert patrouillent sur ses berges. Près de la côte, une grotte s'ouvre dans les collines. C'est un repaire de murlocs, et l'on dit que leur chef, celui que les orcs appellent le {link:swamp-talker}Swamp Talker{/link}, y demeure. Des ordres de la {link:horde}Horde{/link} disparurent dans cette grotte avec les murlocs qui s'en étaient emparés.]=],
		},
	},
})

Translate("frFR", "splinterspear-junction", {
	title = "Croisement de Lance-brisée",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Croisement de Lance-brisée est un carrefour à l'ouest du marais. Ici, la route du {link:deadwind-pass}Défilé de Deuillevent{/link} rejoint le chemin qui file vers le sud en direction des {link:blasted-lands}Terres foudroyées{/link} et de {link:nethergarde-keep}Rempart-du-Néant{/link}. Chaque caravane de l'{link:alliance}Alliance{/link} en route pour la forteresse doit passer par là, et toutes ne passent pas intactes. L'épave de l'une d'elles gît près de la route, où son dernier garde veille encore sur ce que les Perdus ont laissé.]=],
		},
	},
})

Translate("frFR", "the-shifting-mire", {
	title = "Le Bourbier changeant",
	aliases = { "Bourbier changeant" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bourbier changeant est le cœur du pays humide du marais, un dédale de mares et de sols mouvants entre {link:stonard}Stonard{/link} et les routes de l'ouest. Ses sentiers changent à chaque pluie, et aucune carte n'en reste longtemps fidèle. De jeunes crocilisques se chauffent sur ses bancs de boue, et des tisseuses des chagrins tendent leurs toiles entre les arbres noyés. Les orcs de Stonard y envoient des éclaireurs, et tous ne reviennent pas.]=],
		},
	},
})

Translate("frFR", "itharius", {
	title = "Itharius",
	subtitle = "Dragon du vol vert",
	found = "Caverne d'Itharius, au sud-ouest du marais",
	hint = [=[Cherchez le dragon qui demeure dans une caverne au sud-ouest du marais.]=],
	allegiance = "Vol vert · Vol d'Ysera",
	sections = {
		{
			title = "Résumé",
			text = [=[Itharius est un dragon du vol vert, le vol d'{red:ysera}Ysera{/red}, qui garde le {link:emerald-dream}Rêve d'émeraude{/link}. Il a son antre dans une caverne à la lisière sud-ouest du marais, loin du {link:pool-of-tears}Bassin des larmes{/link} où veillent les autres dragons de son espèce. Des dragonnets de son vol dorment dans le marécage autour de sa porte. Il parle peu de lui-même. Il est patient et grave, et il juge les mortels aux choix qu'ils font.]=],
		},
		{
			title = "Importance",
			text = [=[Les dragons verts vinrent dans le marais pour empêcher les prêtres d'{link:hakkar}Hakkar{/link} de rappeler leur dieu dans le monde. La plupart d'entre eux ne souffrent aucun mortel près d'eux. Itharius est le seul membre de leur garde qui parle aux mortels en allié, et qui leur demande de l'aide.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il a son antre à la lisière du marais, à l'écart des dragons du {link:pool-of-tears}Bassin des larmes{/link}.
• Il parle aux mortels de loin par une pierre de serment, une pierre liée à la charge de son vol.
• Il veille sur les jeunes dragonnets de son vol.
• Il envoie ses alliés mortels jusqu'au {link:winterspring}Berceau-de-l'Hiver{/link} en quête d'aide.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit depuis combien de temps Itharius demeure dans le marais, ni pourquoi il garde son antre si loin du temple englouti. Son âge et son rang parmi les dragons verts sont inconnus.]=],
		},
	},
	chapters = {
		{
			title = "La pierre de serment",
			hint = [=[Apportez au dragon une gemme qui renferme l'essence de l'un des siens.]=],
			text = [=[Eranikus, du vol vert, avait pour charge d'empêcher à jamais les Atal'ai de faire revenir leur dieu. Cette charge a échoué, et la corruption du temple s'est emparée de lui. Une part de son esprit, encore sienne, fut liée dans une gemme et emportée hors des salles englouties. Par une pierre de serment, Itharius demande cette gemme. Il ne promet pas que la route sera courte. Il dit seulement qu'une âme qui mérite d'être sauvée mérite le sacrifice.]=],
		},
		{
			title = "Une voix pour le dormeur",
			hint = "Suivez le conseil du dragon jusqu'à l'extrême nord.",
			text = [=[Eranikus gît entre le sommeil et la mort, pris dans une toile de cauchemars. Son essence est gravement souillée, mais Itharius croit qu'on peut encore l'atteindre. Il envoie son allié au nord, dans les neiges de l'est du {link:winterspring}Berceau-de-l'Hiver{/link}, auprès d'un médium humain appelé {link:umbranse-the-spiritspeaker}Umbranse{/link} le Parleur d'esprits, qui parle pour les morts. Eranikus n'est pas mort, mais Itharius espère qu'un tel don pourra l'atteindre malgré tout.]=],
		},
	},
	mentions = {
		{ text = "L'essence d'Eranikus" },
		{ text = "Selon les propres mots d'Eranikus" },
		{
			text = [=[Poussière de rêve dans le marais, recueillie sur les dragonnets de son vol]=],
		},
	},
	bonds = {
		{ id = "eranikus", name = "Eranikus", note = "un dragon de son vol qu'il cherche à racheter" },
		{ id = "umbranse-the-spiritspeaker", name = "Umbranse le Parleur d'esprits", note = "un allié mortel au Berceau-de-l'Hiver" },
	},
})

Translate("frFR", "fel-zerul", {
	title = "Fel'zerul",
	subtitle = "Émissaire du chef de guerre",
	found = "Stonard, dans la grande salle",
	hint = "Parlez à l'orc de Stonard qui étudie le temple englouti.",
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Résumé",
			text = [=[Fel'zerul est l'{link:orcs}orc{/link} que le chef de guerre {link:thrall}Thrall{/link} envoya au {link:swamp-of-sorrows}Marais des Chagrins{/link} pour découvrir quelles choses étranges se passaient au temple d'{link:temple-of-atal-hakkar}Atal'Hakkar{/link}. Il s'attendait à un temple troll rempli de sombres lanceurs de sorts. Il trouva à la place un lac, le temple englouti sous ses eaux et des dragons verts montant la garde sur la rive. Depuis, il travaille depuis {link:stonard}Stonard{/link} à reconstituer l'histoire à partir de débris laissés par les Atal'ai.]=],
		},
		{
			title = "Importance",
			text = [=[Fel'zerul incarne une {link:horde}Horde{/link} qui veut comprendre les puissances de son monde. Il craint les Atal'ai, mais il croit aussi que leurs sorts pourraient un jour servir la Horde. Par son étude patiente, la Horde apprend l'existence du prophète qui mène le temple et du rituel qui pourrait ramener le {link:hakkar}dieu du sang{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rassemble les idoles et les fétiches des Atal'ai autour du {link:pool-of-tears}Bassin des larmes{/link}.
• Ses éclaireurs rapportent une sentence d'exil écrite dans le sang sur une peau séchée.
• Il envoie les reliques du temple au nord, à un prêtre exilé des Atal'ai, dans les {link:the-hinterlands}Hinterlands{/link}.
• Il envoie des champions de la {link:horde}Horde{/link} dans le temple englouti lui-même.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit de la vie de Fel'zerul avant que le chef de guerre ne l'envoie au marais.]=],
		},
	},
	chapters = {
		{
			title = "Les reliques du bassin",
			hint = [=[Rassemblez ce que les Atal'ai ont laissé sur les rives du Bassin des larmes.]=],
			text = [=[Personne à {link:stonard}Stonard{/link} ne savait ce que les Atal'ai avaient fait dans leur temple. Fel'zerul savait seulement qu'une grande magie y avait été à l'œuvre, et que quelque chose avait très mal tourné. Il commença par les reliques qui gisaient dans la boue des rives du lac. Il les étudia une à une, cherchant à apprendre ce que les trolls avaient espéré accomplir.]=],
		},
		{
			title = "L'avertissement de l'exilé",
			hint = [=[Portez les reliques du temple à celui que les Atal'ai ont chassé.]=],
			text = [=[Un éclaireur lui apporta une sentence de jugement, écrite dans le sang sur de la chair séchée. Elle nommait un prêtre des Atal'ai condamné à l'exil parmi les {link:witherbark-trolls}trolls Witherbark{/link} des {link:the-hinterlands}Hinterlands{/link}. Fel'zerul envoya les reliques à cet exilé. La réponse qui revint était grave. Les reliques étaient inoffensives, disait l'exilé. Mais le grand prêtre {link:jammal-an-the-prophet}Jammal'an{/link} avait une prophétie, et s'il avait trouvé le bon enchantement pour ses fétiches, le monde entier était en péril.]=],
		},
		{
			title = "Les fétiches d'Hakkar",
			hint = [=[Entrez dans le temple englouti et emparez-vous des fétiches des Atal'ai.]=],
			text = [=[{link:jammal-an-the-prophet}Jammal'an le Prophète{/link} croit qu'au retour d'{link:hakkar}Hakkar{/link}, le dieu donnera aux Atal'ai la vie éternelle. Fel'zerul y voit une supercherie qui apportera la ruine avant l'heure. Il craint moins la prophétie que les fétiches qui pourraient l'accomplir. Il envoya des champions de la {link:horde}Horde{/link} au fond du temple pour s'en emparer. Quand ils revinrent les fétiches en main, il les nomma champions de la Horde.]=],
		},
	},
	mentions = {
		{ text = "Le {link:pool-of-tears}Bassin des larmes{/link}" },
		{ text = "L'exilé atal'ai" },
		{ text = "Retour auprès de Fel'Zerul" },
		{ text = "{link:temple-of-atal-hakkar}Le temple d'Atal'Hakkar{/link}" },
	},
	bonds = {
		{ id = "atal-ai-exile", name = "Exilé atal'ai", note = "le prêtre paria qui déchiffre ses reliques" },
		{ id = "thrall", name = "Thrall", note = "le chef de guerre qui l'envoya" },
	},
})

Translate("frFR", "fallen-hero-of-the-horde", {
	title = "Héros déchu de la Horde",
	subtitle = "Esprit du marais",
	found = [=[La lisière sud du marais, au bord de la route des Terres foudroyées]=],
	hint = [=[Cherchez l'esprit sans repos qui attend au bord de la route du sud.]=],
	allegiance = "Horde (autrefois)",
	aliases = { "Héros déchu" },
	sections = {
		{
			title = "Résumé",
			text = [=[Près de la route qui descend vers les {link:blasted-lands}Terres foudroyées{/link} se tient le fantôme d'un guerrier de la {link:horde}Horde{/link}. De son vivant, il commandait un régiment appelé {link:thrall}Thrall{/link}'s Grasp. Il le mena dans les Terres foudroyées sans attendre ses ordres, et le régiment fut anéanti. Désormais, il se tient là où il tomba, attendant toujours des ordres qui ne sont jamais venus. Il ne peut porter un coup lui-même. Il ne peut que demander l'aide des vivants, et il la demande aussi bien aux guerriers de l'{link:alliance}Alliance{/link} qu'à ceux de la Horde.]=],
		},
		{
			title = "Importance",
			text = [=[Le Héros déchu est le témoin d'une guerre que la majeure partie du monde a oubliée. Au-delà des ruines de la {link:dark-portal}Porte des Ténèbres{/link}, des démons règnent encore sur les {link:blasted-lands}Terres foudroyées{/link} sous un seigneur appelé {link:razelikh-the-defiler}Razelikh{/link} le Profanateur. Le Héros déchu le sait mieux que quiconque parmi les vivants. Il enseigne que le véritable ennemi n'est ni l'{link:alliance}Alliance{/link} ni la {link:horde}Horde{/link}, mais la Légion qui les attend toutes deux.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena le régiment {link:thrall}Thrall{/link}'s Grasp dans les {link:blasted-lands}Terres foudroyées{/link} avant que ses ordres ne lui parviennent.
• Il appelle les vivants à libérer les âmes de ses hommes et à briser le pouvoir du seigneur démon.
• Il accueille l'{link:alliance}Alliance{/link} pour combattre aux côtés de la {link:horde}Horde{/link} contre les démons.
• Il met à l'épreuve les guerriers de tous les peuples et récompense ceux qui s'en montrent dignes.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit de la vie de ce guerrier avant que {link:thrall}Thrall{/link}'s Grasp ne soit envoyé au sud. Trebor était-il son propre nom ? L'esprit de {link:kirith-the-damned}Kirith{/link} ne le dit pas clairement.]=],
		},
	},
	chapters = {
		{
			title = "Les ordres disparus",
			hint = [=[Découvrez ce qu'il advint des ordres que le commandant déchu ne reçut jamais.]=],
			text = [=[Dans la mort, il ne pouvait penser qu'aux ordres. Le commandant des estafettes {link:dispatch-commander-ruag}Ruag{/link}, de {link:stonard}Stonard{/link}, jurait les avoir envoyés. Ses estafettes tombèrent dans une embuscade de murlocs sur la route, et une seule survécut. Ce survivant, {link:bengor}Bengor{/link}, pouvait à peine parler. Il dit qu'un {link:murlocs}murloc{/link} appelé le {link:swamp-talker}Swamp Talker{/link} lui avait arraché les ordres des mains et s'était enfui vers l'est jusqu'à une grotte. Le Héros déchu apprit que ses hommes n'auraient pas dû mourir. Dix-neuf d'entre eux auraient pu être épargnés, s'il avait seulement attendu.]=],
		},
		{
			title = "Les pierres qui lient",
			hint = [=[Libérez les âmes du régiment tombé des pierres des Terres foudroyées.]=],
			text = [=[Les démons ne laissèrent pas reposer les soldats de {link:thrall}Thrall{/link}'s Grasp. Leurs âmes furent liées dans des pierres dispersées à travers les {link:blasted-lands}Terres foudroyées{/link}, dix-huit en tout. Ce n'est que lorsque les pierres furent brisées que les hommes purent trouver la paix. Quand la dernière vola en éclats, le Héros déchu sut que sa longue dette commençait à être payée.]=],
		},
		{
			title = "Le lieutenant perdu",
			hint = [=[Cherchez le sort du seul lieutenant qu'on ne retrouva jamais.]=],
			text = [=[L'un de ses officiers manquait encore. Le {link:kirith-the-damned}lieutenant Kirith{/link} avait été emprisonné et torturé à ses côtés dans les grottes d'un démon nommé {link:archmage-allistarj}Allistarj{/link}, mais la volonté de Kirith avait cédé sous la torture. Le Héros déchu entendit ses cris depuis sa propre cage, puis n'entendit plus rien. Quand l'esprit de Kirith fut enfin retrouvé, il répondit par un nom : Trebor.]=],
		},
		{
			title = "Le Profanateur",
			hint = [=[Réunissez l'amulette brisée et affrontez le seigneur démon des Terres foudroyées.]=],
			text = [=[{link:razelikh-the-defiler}Razelikh{/link} le Profanateur régnait sur les {link:blasted-lands}Terres foudroyées{/link} par trois serviteurs. Chacun portait un tiers d'une amulette, et tant qu'ils la détenaient, ils ne pouvaient mourir sur les terres du démon. Le Héros déchu envoya ses champions briser les trois et reformer l'amulette entière, puis gravir jusqu'à l'antre du démon sur le plus haut sommet. Quand le Profanateur tomba, le Héros déchu demanda sa corne. Il voulait qu'elle soit la preuve que des héros vivent encore dans un monde brisé par la guerre.]=],
		},
	},
	mentions = {
		{ text = "La chute" },
		{ text = "Le déshonoré" },
		{
			text = [=[Petites querelles, l'{link:alliance}Alliance{/link} vient à son aide]=],
		},
		{ text = "Un récit de chagrin" },
		{ text = "Les héros d'antan, avec l'esprit du caporal Thund Splithoof" },
		{ text = "Le couvert des ténèbres" },
		{ text = "Le chasseur de démons" },
		{ text = "Retour aux {link:blasted-lands}Terres foudroyées{/link}" },
		{ text = "Réunir l'amulette brisée" },
		{ text = "Un esprit tourmenté" },
		{ text = "Parenté guerrière" },
		{ text = "Guerre contre les Voués à l'ombre" },
		{ text = "Plumes vaudou" },
	},
	bonds = {
		{ id = "dispatch-commander-ruag", name = "Commandant des estafettes Ruag", note = "envoya les ordres qui ne vinrent jamais" },
		{ id = "bengor", name = "Bengor", note = "la dernière estafette qui les porta" },
		{ id = "swamp-talker", name = "Swamp Talker", note = "prit les ordres" },
		{ id = "corporal-thund-splithoof", name = "Caporal Thund Splithoof", note = "l'un de ses hommes" },
		{ id = "razelikh-the-defiler", name = "Razelikh le Profanateur", note = "ennemi" },
	},
})

Translate("frFR", "dispatch-commander-ruag", {
