	},
})

Translate("frFR", "helgrum-the-swift", {
	title = "Helgrum le Rapide",
	subtitle = "Maître des coursiers de Stonard",
	found = "Stonard",
	hint = "Parlez à l'orc rapide qui dirige les coursiers de Stonard.",
	allegiance = "Horde · Stonard",
