• Il lit les rapports du nord et les pèse pour {link:stonard}Stonard{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:neeka-bloodscar}Neeka Bloodscar{/link}" },
		{ text = "Au rapport auprès d'Helgrum" },
	},
	bonds = {
		{ id = "neeka-bloodscar", name = "Neeka Bloodscar", note = "cheffe des éclaireurs de Kargath" },
	},
})

Translate("frFR", "dar", {
	title = "Dar",
	subtitle = "Marchand de Stonard",
	found = "Stonard, près de l'auberge",
	hint = [=[Trouvez le marchand de Stonard qui expédie de la viande à Orgrimmar.]=],
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Résumé",
			text = [=[Dar est un marchand de {link:stonard}Stonard{/link}. Il rassemble des vivres pour le camp de la {link:horde}Horde{/link} sur la plage de l'est, et il expédie la viande de la côte à ses clients d'{link:orgrimmar}Orgrimmar{/link}, qui prisent par-dessus tout les pattes des grands rampants. Il goûte toujours la marchandise d'abord, et il garde un tonneau de vin pour ceux qui lui apportent ce qu'il veut. Les orcs de la plage disent que ses manières valent mieux que son odeur, mais de peu.]=],
		},
		{
			title = "Importance",
