		{
			title = "Hauts faits",
			text = [=[• Il envoie de la viande et des vivres à l'est, au Poste de Brumejonc.
• Il expédie de la viande de rampant à {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Pénurie de surplus" },
		{ text = "Viande fraîche" },
	},
	bonds = {
		{ id = "tok-kar", name = "Tok'Kar", note = "reçoit ses vivres" },
	},
})

Translate("frFR", "tok-kar", {
