	subtitle = "Forgeron du Poste de Brumejonc",
	found = "Poste de Brumejonc, sur la plage de l'est",
	hint = [=[Trouvez l'orc qui forge des armes au camp de la Horde sur la plage de l'est.]=],
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Résumé",
			text = [=[Tok'Kar sert au Poste de Brumejonc, la vigie de la {link:horde}Horde{/link} sur la côte est. Entre ses tours de garde, il cuisine pour ses camarades et forge leurs armes, et il est devenu rapide et habile dans les deux. Il façonne des lames à partir des pinces des happeurs dents-de-scie. Il ne regrette pas son poste. Il aimerait seulement, un jour, une vraie tour pour le tenir.]=],
		},
