		{
			title = "Hauts faits",
			text = [=[• Il monte la garde sur l'approche de {link:stonard}Stonard{/link} depuis la mer.
• Il forge des armes avec les pinces des happeurs de la côte.]=],
		},
	},
	mentions = {
		{ text = "Pénurie de surplus" },
		{ text = "Pénurie de surplus" },
		{ text = "La menace venue de la mer" },
		{ text = "La menace venue de la mer" },
	},
	bonds = {
		{ id = "katar", name = "Katar", note = "son camarade de la plage" },
		{ id = "dar", name = "Dar", note = "lui envoie des vivres" },
	},
})

Translate("frFR", "katar", {
	title = "Katar",
	subtitle = "Guetteur de la mer",
	found = "Poste de Brumejonc, sur la plage de l'est",
	hint = "Parlez à l'orc du camp de la plage qui hait la mer.",
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Résumé",
			text = [=[Katar monte la garde sur la plage du Poste de Brumejonc. Il hait la mer, et il hait toutes les créatures qui en sortent, les murlocs plus que tout. Il se dit aussi patient qu'une vieille pierre de {red:draenor}Draenor{/red}. Il jure que les hommes-poissons ne franchiront pas les frontières de la {link:horde}Horde{/link} tant qu'il tiendra debout, et il ne sourit que lorsqu'il les entend mourir.]=],
		},
		{
